samples.proof:
have h_main : x^2 - 6 * x + y^2 ≤ 8 := by
  cases' le_total 0 (x + y) with h₁ h₁ <;>
  cases' le_total 0 (x - y) with h₂ h₂ <;>
  simp_all only [abs_of_nonneg, abs_of_nonpos, add_left_neg, add_right_neg, add_assoc] <;>
  (try { nlinarith [sq_nonneg (x + y), sq_nonneg (x - y)] }) <;>
  (try {
    cases' le_total 0 (x - 1) with h₃ h₃ <;>
    cases' le_total 0 (y - 1) with h₄ h₄ <;>
    nlinarith [sq_nonneg (x + y), sq_nonneg (x - y)]
  }) <;>
  (try {
    cases' le_total 0 (x + 1) with h₃ h₃ <;>
    cases' le_total 0 (y + 1) with h₄ h₄ <;>
    nlinarith [sq_nonneg (x + y), sq_nonneg (x - y)]
  }) <;>
  (try {
    nlinarith [sq_nonneg (x + y), sq_nonneg (x - y)]
  })
  <;>
  (try {
    nlinarith [sq_nonneg (x - 1), sq_nonneg (y - 1)]
  })
  <;>
  (try {
    nlinarith [sq_nonneg (x + 1), sq_nonneg (y + 1)]
  })
exact h_main
